# Comparison with R survival::clogit(method = "exact") (same likelihood as SAS STRATA).
# Fixtures: test/reference/*.json, generated by test/reference/generate_reference.R.
#
# Two kinds of comparison:
#  * "tight": our fit with gconv = 1e-16 (fully converged) vs R run with eps = 1e-14.
#  * "sas":   our default SAS-mode fit (GCONV = 1e-8, iterate reported without the extra
#             step); estimates may differ from the exact optimum by ~1e-6 relative.
#  * at a fixed β (R iter.max = 0): log-likelihood, score statistic and covariance from
#    our kernel vs R, with no dependence on any stopping rule.

const TIGHT = (gconv = 1e-16, maxiter = 50)

function compare_fit(m, ref; tight::Bool = true)
    al = Bool.(ref["aliased"])
    k = .!al
    @test aliased(m) == al
    @test dof(m) == ref["df"]
    @test all(iszero, coef(m)[al])
    @test all(isnan, stderror(m)[al])
    rc = tight ? 1e-8 : 1e-4
    @test coef(m)[k] ≈ jvec(ref["coef"])[k] rtol = rc
    @test stderror(m)[k] ≈ jvec(ref["se"])[k] rtol = (tight ? 1e-8 : 1e-4)
    @test vcov(m)[k, k] ≈ jmat(ref["vcov"])[k, k] rtol = (tight ? 1e-8 : 1e-4)
    @test loglikelihood(m) ≈ ref["loglik"] rtol = (tight ? 1e-13 : 1e-9)
    @test nullloglikelihood(m) ≈ ref["loglik0"] rtol = 1e-13
    gt = globaltests(m)
    @test gt.lr.chisq ≈ ref["lr"] rtol = (tight ? 1e-10 : 1e-7)
    @test gt.score.chisq ≈ ref["score"] rtol = 1e-11       # at β = 0: no convergence dependence
    @test gt.wald.chisq ≈ ref["wald"] rtol = (tight ? 1e-8 : 1e-4)
    return nothing
end

function check_at_beta(df, ref, covs; strata, y = :y, offset = nothing)
    ab = ref["at_beta"]
    β = jvec(ab["beta"])
    X = Matrix{Float64}(df[:, covs])
    codes, _ = CL.strata_codes(df[!, strata])
    off = offset === nothing ? zeros(nrow(df)) : Vector{Float64}(df[!, offset])
    d, _ = design_of(X, BitVector(df[!, y] .== 1), codes, ones(Int, nrow(df)), off)
    ℓ, g, I = eval_design(d, β)
    @test ℓ ≈ ab["loglik"] rtol = 1e-13
    @test inv(I) ≈ jmat(ab["vcov"]) rtol = 1e-11
    @test dot(g, I \ g) ≈ ab["score"] rtol = 1e-10
end

@testset "LOGIEX11 (la)" begin
    df, refs = load_fixture("la")
    compare_fit(clogit(@formula(y ~ gall), df; strata = :s, TIGHT...), refs["la_gall"])
    compare_fit(clogit(@formula(y ~ gall), df; strata = :s), refs["la_gall"]; tight = false)
    compare_fit(clogit(@formula(y ~ gall + hyper), df; strata = :s, TIGHT...),
                refs["la_gall_hyper"])
    compare_fit(clogit(@formula(y ~ gall + hyper), df; strata = :s), refs["la_gall_hyper"];
                tight = false)
    check_at_beta(df, refs["la_gall"], [:gall]; strata = :s)
    check_at_beta(df, refs["la_gall_hyper"], [:gall, :hyper]; strata = :s)
end

@testset "infert (m_k = 1, aliasing)" begin
    df, refs = load_fixture("infert")
    m = clogit(@formula(case ~ spontaneous + induced), df; strata = :stratum, TIGHT...)
    compare_fit(m, refs["infert_si"])
    @test nobs(m) == refs["infert_si"]["n"] == 248
    compare_fit(clogit(@formula(case ~ spontaneous + induced), df; strata = :stratum),
                refs["infert_si"]; tight = false)
    check_at_beta(df, refs["infert_si"], [:spontaneous, :induced]; strata = :stratum, y = :case)
    # education is constant within strata -> aliased (R: NA)
    me = @test_logs (:warn, r"set to 0") clogit(@formula(case ~ spontaneous + induced + education),
                                                df; strata = :stratum, TIGHT...)
    compare_fit(me, refs["infert_si_edu"])
    @test coef(me)[1:2] ≈ coef(m) rtol = 1e-12
end

@testset "synthetic m_k > 1, unequal strata, uninformative strata" begin
    df, refs = load_fixture("synth_mk")
    covs = [:x1, :x2, :x3]
    m = clogit(@formula(y ~ x1 + x2 + x3), df; strata = :id, TIGHT...)
    compare_fit(m, refs["synth_x"])
    s = stratasummary(m)
    @test s.nuninformative > 0
    @test m.nobs_used == refs["synth_x"]["n"]
    @test count(response(m)) == refs["synth_x"]["nevent"]
    compare_fit(clogit(@formula(y ~ x1 + x2 + x3), df; strata = :id), refs["synth_x"];
                tight = false)
    check_at_beta(df, refs["synth_x"], covs; strata = :id)

    # categorical covariate (treatment coding, base = first level, as R)
    mg = clogit(@formula(y ~ x1 + x2 + x3 + g), df; strata = :id, TIGHT...)
    compare_fit(mg, refs["synth_xg"])
    @test coefnames(mg) == ["x1", "x2", "x3", "g: b", "g: c"]

    # SAS default ordering: event = 0 == R fit of 1 - y
    m0 = clogit(@formula(y ~ x1 + x2 + x3), df; strata = :id, event = 0, TIGHT...)
    compare_fit(m0, refs["synth_x_event0"])
    @test coef(m0) ≈ -coef(m) rtol = 1e-10
    @test loglikelihood(m0) ≈ loglikelihood(m) rtol = 1e-13
    @test stderror(m0) ≈ stderror(m) rtol = 1e-10
    compare_fit(clogit(@formula(noty ~ x1 + x2 + x3), df; strata = :id, TIGHT...),
                refs["synth_x_event0"])

    # offset
    mo = clogit(@formula(y ~ x1 + x2 + x3), df; strata = :id, offset = :off, TIGHT...)
    compare_fit(mo, refs["synth_x_offset"])
    check_at_beta(df, refs["synth_x_offset"], covs; strata = :id, offset = :off)
end

@testset "missing values (listwise deletion)" begin
    df, refs = load_fixture("synth_missing")
    m = clogit(@formula(y ~ x1 + x2 + x3), df; strata = :id, TIGHT...)
    compare_fit(m, refs["synth_missing_x"])
    @test m.nobs_read == nrow(df)
    @test m.nobs_used == refs["synth_missing_x"]["n"]
    @test m.nobs_used == nrow(dropmissing(df))
end

@testset "large strata (n = 200, m up to 170)" begin
    df, refs = load_fixture("synth_big")
    m = clogit(@formula(y ~ x1 + x2), df; strata = :id, TIGHT...)
    compare_fit(m, refs["synth_big_x"])
    check_at_beta(df, refs["synth_big_x"], [:x1, :x2]; strata = :id)
end

@testset "FREQ = row replication" begin
    df, refs = load_fixture("synth_freq")
    m = clogit(@formula(y ~ x1 + x2), df; strata = :id, freq = :f, TIGHT...)
    ref = refs["synth_freq_x"]
    compare_fit(m, ref)
    @test m.freq_used == ref["n"]
    @test nobs(m) == sum(df.f)
    ex = df[reduce(vcat, [fill(i, df.f[i]) for i in 1:nrow(df)]), :]
    me = clogit(@formula(y ~ x1 + x2), ex; strata = :id, TIGHT...)
    @test coef(me) ≈ coef(m) rtol = 1e-11
    @test vcov(me) ≈ vcov(m) rtol = 1e-10
    @test loglikelihood(me) ≈ loglikelihood(m) rtol = 1e-13
    @test bic(me) ≈ bic(m) rtol = 1e-13
    mw = clogit(@formula(y ~ x1 + x2), df; strata = :id, weights = fweights(df.f), TIGHT...)
    @test coef(mw) == coef(m)
end
